entries[104198] = { ["name"] = "Ausrüstung des Mantisartefaktjägers", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Die Lehrensucher\n- Ehrfürchtig\n\"Enthält ein Sonar für Mantisartefakte, durch das sämtliche neue Ausgrabungsstätten, die Ihr in Pandaria entdeckt, einen Tag lang zu Mantisausgrabungsstätten werden. Enthält außerdem eine Karte des Lehrensuchers.\"\n<Zum Öffnen rechtsklicken>" }
entries[104202] = { ["name"] = "Flipps", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Flipps, den boxenden Ho-zen beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[104208] = { ["name"] = "Zügel von Galakras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr eine Brut von Galakras beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Brut von Galakras oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Stammbaum dieser beachtlichen Kreatur kann bis zu Galakras und sogar weiter bis zu Galakrond, einem der berüchtigsten Protodrachen, zurückverfolgt werden.\"\nErfolg:\nRuhm des Schlachtzüglers von Orgrimmar\nKategorie:\nDungeons & Schlachtzüge" }
