entries[104223] = { ["name"] = "Technik: Glyphe 'Unbändiger Elementar'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Unbändiger Elementar' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Unbändiger Elementar'\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch einen unbändigen Wasserelementar ersetzt. Exklusiv mit: Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Jadefeuertinte (3)" }
entries[104224] = { ["name"] = "Technik: Glyphe 'Verdampfen'", ["text"] = "Benutzen: Lehrt Euch, wie man die Glyphe 'Verdampfen' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Verdampfen'\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Wasserelementars um 15%. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Löwentinte (3)" }
