entries[104227] = { ["name"] = "Technik: Glyphe 'Säule des Lichts'", ["text"] = "Benutzen: Lehrt Euch, wie man die Glyphe 'Säule des Lichts' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Säule des Lichts'\nKlassen: Paladin\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Heilungen von 'Heiliger Schock' bei anderen Spielercharakteren erzeugen kurzzeitig eine Lichtsäule an deren Standort.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)" }
entries[104228] = { ["name"] = "Technik: Glyphe 'Engel'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Engel' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Engel'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBeim Wirken von Heilzaubern besteht eine Chance, dass Ihr Engelsflügel erhaltet. (Procchance: 15%)\nVerkaufspreis:\nBenötigt Leichtes Pergament , Meerestinte (3)" }
entries[104229] = { ["name"] = "Technik: Glyphe 'Sha'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Sha' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Sha'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in eine Sha-Bestie. Exklusiv mit: Glyphe 'Lichtbrut' Glyphe 'Leerenekel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Astraltinte (3)" }
