entries[104231] = { ["name"] = "Technik: Glyphe 'Inspirierte Hymnen'", ["text"] = "Benutzen: Lehrt Euch, wie man die Glyphe 'Inspirierte Hymnen' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Inspirierte Hymnen'\nKlassen: Priester\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Hymnen kanalisiert, erscheint ein Geist über Euch.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Mondlichttinte (3)" }
