entries[104234] = { ["name"] = "Technik: Glyphe 'Geisterraptoren'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Geisterraptoren' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Geisterraptoren'\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Geisterwölfe werden durch Geisterraptoren ersetzt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Löwentinte (3)" }
entries[104235] = { ["name"] = "Technik: Glyphe 'Beistand der Ahnen'", ["text"] = "Benutzen: Lehrt Euch, wie man die Glyphe 'Beistand der Ahnen' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\nGlyphe 'Beistand der Ahnen'\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn ein Spielercharakter mittels 'Geist der Ahnen' wiederbelebt wird, folgt ihm ein Ahnengeist für kurze Zeit.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Mitternachtstinte (3)" }
