entries[104245] = { ["name"] = "Technik: Glyphe 'Waffenmeister'", ["text"] = "Benutzen: Lehrt Euch, wie man die Glyphe 'Waffenmeister' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Waffenmeister'\nKlassen: Krieger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Tollkühnheit' lässt Eure Waffe für 10 Min. das Aussehen einer zufälligen Waffe aus Eurer Tasche annehmen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Firmamenttinte (3)" }
entries[104246] = { ["name"] = "Zügel des Kriegswolfs der Kor'kron", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Kriegswolf der Kor'kron beschwört. Das ist ein Bodenreittier.\nBeschwört einen Kriegswolf der Kor'kron oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Kor'kron nutzen nur die mächtigsten Wölfe als Reittiere und kleiden sie in Rüstungen, die schwächere Kreaturen in die Knie zwingen würden.\"\nErfolg:\nDer Zeit voraus: Garrosh Höllschrei (10/25 Spieler)\nKategorie:\nHeldentaten" }
