entries[104253] = { ["name"] = "Koloss der Kor'kron", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Koloss der Kor'kron beschwört. Das ist ein Bodenreittier.\nBeschwört einen Koloss der Kor'kron oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Koloss der Kor'kron ist ein Verbreiter ungezügelter Zerstörung, der den Ideen von Garrosh Höllschrei entsprang und durch seine Ingenieure verwirklicht wurde.\"\nBeute von:\nGarrosh Höllschrei\nOrt:\nSchlacht um Orgrimmar" }
