entries[104280] = { ["name"] = "Verdrehte Schriftrolle", ["text"] = "Einzigartig\nBenötigt Inschriftenkunde von Pandaria (1)\n\"Dieses Rezept wurde durch irgendeine Form von Magie zerstört.\"\nVerkaufspreis:" }
entries[104281] = { ["name"] = "Veraltete Technik", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Es sieht zwar aus, als wäre diese Technik veraltet und könne Euch nicht mehr lehren, wie man eine Glyphe schreibt, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"" }
entries[104286] = { ["name"] = "Zitterndes Feuersturmei", ["text"] = "Wird an Kriegsmeute gebunden\n\"Ein sehr seltenes Ei. Es sieht aus, als wenn bald etwas daraus schlüpfen würde. Die Älteste Anli im Arboretum würde das sicherlich gerne sehen.\"" }
entries[104287] = { ["name"] = "Windfeder", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht 1 Stunde lang die Geschwindigkeit um 30%, während Ihr ein nicht fliegendes Reittier reitet. Kann nur in Pandaria verwendet werden.\n\"Die Federn des Windfederkranichs sind überraschend leicht und wehen schon beim sanftesten Lufthauch davon.\"" }
entries[104288] = { ["name"] = "Kondensierter Jadenebel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Umgebt Euch mit einem dichten Nebel und ermöglicht Euch so, 10 Sek. lang mit den Schatten zu verschmelzen. Kann nur in Pandaria verwendet werden. (5 Min Abklingzeit)\n\"Es heißt, die Jadenebeltänzer seien eins mit dem Nebel, der die Insel umgibt.\"" }
entries[104289] = { ["name"] = "Schwach leuchtendes Kraut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 1 tag (Realzeit)\nBenutzen: Der Verzehr des Krauts stellt 10 Sek. lang alle 1 Sek. 206 Gesundheit wieder her.\n\"Diese Pflanze scheint über einen natürlichen Zauber zu verfügen.\"" }
entries[104290] = { ["name"] = "Klebriges Seidenraupenexkret", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Überzieht einen Gegner mit klebriger Seide, wodurch sich selbst das stärkste Geschöpf 20 Sek. lang nicht bewegen kann. Kann nur auf der Zeitlosen Insel verwendet werden. (5 Min Abklingzeit)\n\"Die Seidenraupen der Zeitlosen Insel benutzen einen seltsamen, doch sehr starken Seidenfaden, um ihre Beute zu fangen.\"" }
entries[104291] = { ["name"] = "Schwarmling von Gu'chi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Schwarmling von Gu'chi beschwören oder wieder freigeben.\n80 ( 80)" }
entries[104292] = { ["name"] = "Halbverdaute Mahlzeit", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Schlange hat offensichtlich viel zu viel auf einmal gefressen, denn das Mahl scheint größtenteils ganz und unverdaut zu sein.\"\n<Zum Öffnen rechtsklicken>" }
entries[104293] = { ["name"] = "Krabblerpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Bedeckt Euren Kopf mit einem farbenfrohen Panzer und verringert so 1 Stunde lang den Radius, in dem Gegner Euch entdecken können. Kann nur in Pandaria verwendet werden. (5 Min Abklingzeit)\n\"Die schimmernden Panzer der Dornzangen sind nützlich, um potenzielle Angreifer zu verwirren.\"\nVerkaufspreis:" }
entries[104294] = { ["name"] = "Reif des zeitverlorenen Seefahrers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Singt die eindringliche Melodie der auf dem Schreckensschiff Vazuvius verloren gegangenen Besatzung. (2 Std. Abklingzeit)" }
entries[104295] = { ["name"] = "Harmonisches Stachelschweinchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer harmonisches Stachelschwein beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Kaiser Shaohao\n- Respektvoll" }
entries[104296] = { ["name"] = "Zeremonielle Roben von Ordos", ["text"] = "Wird beim Aufheben gebunden\n\"Diese kunstvoll verzierten verzauberten Roben können in nützliche Bestandteile aufgetrennt werden.\"\n<Zum Öffnen rechtsklicken>" }
entries[104297] = { ["name"] = "Leuchtendes Siegel von Ordos", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lasst geschmolzene Wut auf alle Kleintiere in einem Umkreis von 40 Metern niedergehen.\nVerkaufspreis:" }
entries[104298] = { ["name"] = "Totenglocke von Ordos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 18 Feuerschaden zu und stößt sie für 3 Sek. auf den Boden. (2 Min Abklingzeit)\n\"Die Anhänger von Ordos läuten diese Glocke, bevor Ordos ein Opfer dargebracht wird.\"\nVerkaufspreis:" }
entries[104299] = { ["name"] = "Flammenschnuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schleudert den Benutzer als flammenden Meteor weit weg. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Ein weißglühender Splitter aus dem Inneren von Glutfall.\"\nVerkaufspreis:" }
entries[104302] = { ["name"] = "Schwarzflammendolche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Legt die Schwarzflammendolche an, um Eure Treue zu Ordos zu demonstrieren. (1 Stunde Abklingzeit)\n\"Die Champions von Ordos verwenden diese zeremoniellen Dolche.\"\nVerkaufspreis:" }
entries[104303] = { ["name"] = "Regenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Regenstein, der in der Umgebung 10 Min. lang eine unnatürliche Sturzflut auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Die verspielten Wassergeister Pandarias haben eine merkwürdige Verbindung mit dem Wetter.\"\nVerkaufspreis:" }
entries[104304] = { ["name"] = "Blizzardstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Blizzardstein, der in der Umgebung 10 Min. lang einen unnatürlichen Schneesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Ranghohe Sänger von Ordos können das Wetter kontrollieren, sodass nie Schnee oder Regen auf die ewigen Feuer im Heiligtum von Ordos fällt.\"\nVerkaufspreis:" }
entries[104305] = { ["name"] = "Aschestein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Aschestein, der in der Umgebung 10 Min. lang einen Aschesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Bevor sie angreifen, beschwören die Anhänger von Ordos oft einen Aschesturm, der ihren Feinden die Sicht unmöglich macht.\"\nVerkaufspreis:" }
entries[104306] = { ["name"] = "Sonnenuntergangsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert einen Sonnenuntergangsstein, der die Tageszeit der Umgebung 10 Min. lang zu Sonnenuntergang ändert. (1 Stunde Abklingzeit)\n50 Aufladungen\n\"Eine seltsame und potenziell ziemlich gefährliche Kuriosität, die in einem kleinen Gebiet den Fluss der Zeit anhalten kann.\"\nVerkaufspreis:" }
entries[104307] = { ["name"] = "Jadefeuergeist", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Jadefeuergeist beschwören oder wieder freigeben.\n80 ( 80)" }
entries[104308] = { ["name"] = "Akoliks säuregetränkte Roben", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nBrust Stoff\n4 Rüstung\n+1 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 7 Intelligenz\n\nHaltbarkeit 165 / 165\nVerkaufspreis:" }
entries[104309] = { ["name"] = "Ewiger Flammenkessel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Baut einen ewigen Flammenkessel auf, der die Willenskraft aller in der Nähe um 4 erhöht und das Kochen ermöglicht. (30 Min Abklingzeit)\n\"Anhänger von Ordos nehmen kleine Flammenkessel mit, wenn sie sich auf lange Reisen durch die Wildnis begeben.\"" }
entries[104311] = { ["name"] = "Beinplatten des unüberlegten Streits", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nBeine Platte\n15 Rüstung\n+1 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 1.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 7 Stärke\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[104312] = { ["name"] = "Merkwürdig leuchtender Pilz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Heilt den Benutzer 10 Sek. lang alle 2 Sek. um 5% seiner maximalen Gesundheit und stellt 5% einer klassenspezifischen Primärressource wieder her.\n\"Ein merkwürdiger Pilz aus den Tiefen der Höhle der Verlorenen Geister.\"" }
entries[104313] = { ["name"] = "Goldenes Moos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nAnlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n\"Das Moos ist mit Gold und anderen wertvollen Mineralien gespickt, die sich im Laufe von Jahrtausenden in den feuchten Höhlen gebildet haben.\"\nVerkaufspreis:" }
entries[104314] = { ["name"] = "Drachenbrühe", ["text"] = "Benutzen: Ein überraschend starkes alkoholisches Getränk.\n\"Von Grimmdorn Rotbart persönlich hergestellt.\"\nVerkaufspreis:" }
entries[104316] = { ["name"] = "Spektraler Grog", ["text"] = "Benutzen: Verwandelt Euch in einen Spektralpiraten und macht Euch betrunken. (3 Sek. Abklingzeit)\n\"Verströmt ein jenseitiges Aroma.\"\nVerkaufspreis:" }
entries[104317] = { ["name"] = "Miese Helferbox", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren miesen kleinen Helfer beschwören oder wieder freigeben.\n\nSelbst miese kleine Helfer sind das ganze Jahr über sehr beschäftigt und haben deshalb nur während des Winterhauchfests Zeit, Euch zu begleiten.\n80 ( 80)" }
entries[104318] = { ["name"] = "Steuerung des Krachbummfliegers", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren Flieger. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[104319] = { ["name"] = "Winterhauchgeschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[104320] = { ["name"] = "Verfluchter Talisman", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verbannt den Benutzer 20 Sek. lang. (5 Min Abklingzeit)\n50 Aufladungen\n\"Die Schnitzarbeit auf dem Talisman stellt eine Grotte voller Moos dar. Wenn man die Augen zukneift, kann man im Moosbett beinahe ein Gesicht erkennen.\"" }
entries[104321] = { ["name"] = "Kapitän Zvezdans verlorenes Bein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Stampft mit dem Bein auf den Boden und ruft die Besatzung der Seepocke herbei, um Euch 10 Min. lang im Kampf beizustehen. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[104323] = { ["name"] = "Das runde Schweineleder", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Wenn möglich, wird er ihn zurückwerfen!\n\"Eine luftgefüllte Schweineblase, die in robustes Rindsleder gewickelt ist.\"\nVerkaufspreis:" }
entries[104324] = { ["name"] = "Fußball", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schießt den Ball einem freundlich gesinnten Spieler zu. Wenn möglich, spielt er ihn automatisch zurück.\n\"Eine luftgefüllte Kodoblase, die in robustes Zhevraleder gewickelt ist.\"\nVerkaufspreis:" }
entries[104325] = { ["name"] = "Wolkenschlange des tyrannischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des tyrannischen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In klassischem Schwarz sehen diese Wolkenschlangen immer sehr elegant und schlank aus.\"\nKlassisch" }
entries[104326] = { ["name"] = "Wolkenschlange des erbitterten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des erbitterten Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schuppenfarben dieser strahlend bunten Wolkenschlangen sind eine Mischung aus Rubinrot, Gold und beinahe Violett.\"\nKlassisch" }
entries[104327] = { ["name"] = "Wolkenschlange des stolzen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört eine reitbare Wolkenschlange des stolzen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schuppenfarben dieser strahlend bunten Wolkenschlangen reichen von Gold zu Pink. Aber wir könnten sie auch korallenfarben nennen.\"\nKlassisch" }
entries[104328] = { ["name"] = "Kauterisierender Kern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Aktiviert den Kern und ermöglicht es dem Träger, mit 20% Gesundheit und Mana wiederbelebt zu werden. Kann nur in Pandaria verwendet werden. (1 Stunde Abklingzeit)\n20 Aufladungen\n\"Ein feuriger Kern, der die lebendige Essenz des geschmolzenen Wächters enthält.\"" }
entries[104329] = { ["name"] = "Aschebedecktes Horn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nReittier\n(Accountweit)\nBenutzen: Beschwört ein reitbares, aber unkontrollierbares wütendes Aschefellmushan. Das ist ein sehr, SEHR schnelles Reittier. Kann nur auf der Zeitlosen Insel verwendet werden. (1 Min Abklingzeit)\n\"Immer etwas warm.\"" }
entries[104330] = { ["name"] = "Verformtes Warnschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (3 Sek. Abklingzeit)\n5 Aufladungen\n\"Das Holz dieses Schilds wird nicht lange Bestand haben.\"" }
entries[104331] = { ["name"] = "Warnschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (1 Stunde Abklingzeit)" }
entries[104332] = { ["name"] = "Himmelslaterne", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Eure Himmelslaterne beschwören oder wieder freigeben.\n80 ( 80)" }
entries[104333] = { ["name"] = "Windige Himmelslaterne", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Mit Rechtsklick Eure Himmelslaterne beschwören oder wieder freigeben.\n5 Aufladungen\n80 ( 80)" }
entries[104334] = { ["name"] = "Nebliges Pi'jiubräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Schüttet das Bräu auf den Boden und beschwört so einen spektralen Nebelwirker, der 10 Min. lang für Euch kämpfen wird. (10 Min Abklingzeit)" }
entries[104335] = { ["name"] = "Dickflüssiges Pi'jiubräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Schüttet das Bräu auf den Boden und beschwört so einen spektralen Braumeister, der 10 Min. lang für Euch kämpfen wird. (10 Min Abklingzeit)" }
entries[104336] = { ["name"] = "Blubberndes Pi'jiubräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Schüttet das Bräu auf den Boden und beschwört so einen spektralen Windläufer, der 10 Min. lang für Euch kämpfen wird. (10 Min Abklingzeit)" }
entries[104339] = { ["name"] = "Harmonische Nudeln des Flusses", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Parieren.\n\"Werden gekühlt serviert – beruhigen und schmecken hervorragend.\"\nVerkaufspreis:" }
entries[104340] = { ["name"] = "Nudeln der verrückten Schlange", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Ausweichen.\n\"Leicht giftig, aber schmackhaft!\"\nVerkaufspreis:" }
entries[104341] = { ["name"] = "Dampfende Ziegennudeln", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Tempo.\n\"Diese aromatische Suppe enthält Ziegenfleisch und -milch.\"\nVerkaufspreis:" }
entries[104342] = { ["name"] = "Würzige Mushannudeln", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 kritischen Trefferwert.\n\"Heiß und herzhaft wie die lodernde Seele eines Yaungol!\"\nVerkaufspreis:" }
entries[104343] = { ["name"] = "Golddrachennudeln", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Tempo.\n\"Wohlriechend, butterweich und schmackhaft.\"\nVerkaufspreis:" }
entries[104344] = { ["name"] = "Glückspilznudeln", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 kritischen Trefferwert.\n\"Lecker und nahrhaft.\"\nVerkaufspreis:" }
entries[104345] = { ["name"] = "Zeitloser Anhänger", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erschafft einen seelengebundenen Gegenstand, der für Eure Beutespezialisierung nützlich ist." }
entries[104346] = { ["name"] = "Goldener Gleiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Fliegt auf dem Gleiter und verringert so 2 Min. lang Eure Fallgeschwindigkeit. Kann nur auf der Zeitlosen Insel verwendet werden. (3 Min Abklingzeit)" }
entries[104347] = { ["name"] = "Zeitlose Kuriosität", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erschafft einen seelengebundenen Gegenstand, der für Eure Beutespezialisierung nützlich ist." }
entries[104348] = { ["name"] = "Zeitloser Tee", ["text"] = "Benutzen: Verringert Trunkenheit und stellt im Verlauf von 20 Sek. insgesamt ( 1375 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Ein erfrischender Kräutertee.\"\nVerkaufspreis:" }
