entries[104412] = { ["name"] = "Dreizack der verderbten Wasser", ["text"] = "Mythisch\nWird beim Aufheben gebunden\nZweihändig Stab\n10 - 14 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+3 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\n\nPrismatischer Sockel\nSockelbonus: + 2 Beweglichkeit\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
